{
  "title": "The Ruined Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined city.",
      "visual_description": "Four cloaked figures crouch on a windswept hill at dusk, looking down at a half-collapsed royal city with broken spires and torn banners.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 2,
      "caption": "The map reader traces the safest path inside.",
      "visual_description": "Close-up of a weathered parchment map spread on a rock, a gloved finger tracing a route, lantern light flickering across faded ink.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 3,
      "caption": "They slip past the great castle gates.",
      "visual_description": "Massive iron-banded gates hang crookedly off their hinges; the team presses into shadows beside a fallen portcullis as moonlight spills through.",
      "characters": ["scout", "map_reader", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 4,
      "caption": "Frightened townspeople warn them away.",
      "visual_description": "Ragged civilians huddle in a doorway lit by a single candle, gesturing fearfully toward a dark tower in the distance.",
      "characters": ["scout", "frightened_townsfolk"]
    },
    {
      "scene_number": 5,
      "caption": "An armored patrol marches down the avenue.",
      "visual_description": "A column of helmeted soldiers in dark plate tramps past a ruined fountain; the team flattens against a mossy wall, breath held.",
      "characters": ["armored_patrol", "scout", "map_reader"]
    },
    {
      "scene_number": 6,
      "caption": "The magic helper hushes their footsteps with a spell.",
      "visual_description": "Faint blue runes drift up from the cobblestones around the team's boots; the magic helper's hands glow softly.",
      "characters": ["magic_helper", "scout", "map_reader", "sleepy_official"]
    },
    {
      "scene_number": 7,
      "caption": "Old royal banners hang in tatters above the plaza.",
      "visual_description": "Faded crimson banners with a golden crown crest sway over an empty plaza strewn with leaves and broken statues.",
      "characters": ["map_reader", "sleepy_official"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a dragon stir in the distance.",
      "visual_description": "A long serpentine shadow passes across the moon; the team looks up from a rooftop, faces lit by pale silver light.",
      "characters": ["scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 9,
      "caption": "The sleepy official nearly gives them away with a yawn.",
      "visual_description": "A plump robed figure stretches and yawns loudly; the scout claps a hand over his mouth as a patrol's torch flickers nearby.",
      "characters": ["sleepy_official", "scout", "armored_patrol"]
    },
    {
      "scene_number": 10,
      "caption": "They approach the cursed tower where the captive waits.",
      "visual_description": "A leaning black tower wrapped in violet mist looms over a courtyard of cracked tiles; faint screams echo from above.",
      "characters": ["map_reader", "magic_helper", "scout", "sleepy_official"]
    },
    {
      "scene_number": 11,
      "caption": "A magic door bars their way.",
      "visual_description": "A tall stone door carved with shifting glyphs glows faintly; the magic helper raises both hands as the symbols rearrange.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 12,
      "caption": "The door yields to the right glyph sequence.",
      "visual_description": "The stone door splits down the middle, releasing a gust of dust and lavender light; the team steps through silhouetted.",
      "characters": ["magic_helper", "scout", "map_reader", "sleepy_official"]
    },
    {
      "scene_number": 13,
      "caption": "Inside, they find the captive chained in a cell.",
      "visual_description": "A thin figure in tattered finery slumps against an iron ring set in damp stone, looking up as torchlight floods the cell.",
      "characters": ["captive", "scout", "magic_helper"]
    },
    {
      "scene_number": 14,
      "caption": "The chains are broken and the captive freed.",
      "visual_description": "The magic helper presses a glowing palm to the shackles; iron flakes apart as the captive rubs raw wrists.",
      "characters": ["captive", "magic_helper", "scout"]
    },
    {
      "scene_number": 15,
      "caption": "Alarms sound across the ruined city.",
      "visual_description": "Bells clang from a cracked belfry; red torchlight blooms along the walls as armored figures pour from doorways.",
      "characters": ["armored_patrol", "scout", "map_reader", "captive"]
    },
    {
      "scene_number": 16,
      "caption": "The team flees through the burning streets.",
      "visual_description": "The five run through narrow alleys lit orange by distant fires, the sleepy official puffing at the rear clutching his hat.",
      "characters": ["scout", "map_reader", "magic_helper", "sleepy_official", "captive"]
    },
    {
      "scene_number": 17,
      "caption": "They reach the bridge as it begins to collapse.",
      "visual_description": "A long stone bridge over a deep gorge cracks and crumbles behind them; the bridge_walker strides ahead on impossibly thin remaining stones.",
      "characters": ["bridge_walker", "scout", "map_reader", "magic_helper", "sleepy_official", "captive"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, they look back at the fallen city.",
      "visual_description": "The team stands on a green ridge at dawn, the ruined city smoking across the chasm, the captive wrapped in the scout's cloak.",
      "characters": ["scout", "map_reader", "magic_helper", "sleepy_official", "captive", "bridge_walker"]
    }
  ]
}

